public class Solution {
    public int[] countBits(int n) {
        int[] r = new int[n+1];
        for (int i = 0; i <= n; i++) {
            int x = i, c = 0;
            while (x > 0) { c += x & 1; x >>= 1; }  // O(n log n), для n=10^5 ok, но 10^7 — TLE
            r[i] = c;
        }
        return r;
    }
}

